SourceCode.Declaration:
/// <summary>
/// A store's item list for the handhelds' item sync: the items of its retail assortment, for a
/// warehouse with Sync by assortment on (HSMobileOpsWarehouseControl). The item feeds and the
/// store's snapshot join it on (Warehouse, ItemId), so a store's sync reads only its own items.
/// </summary>
public class HSMobileOpsSyncAssortItem extends common
{
}

Method.Source:
/// <summary>
/// Makes the warehouse's list the store's assortment today: adds what is new, removes what
/// left it; empties it when _on is false. Returns [items in the list, signature]: the SHA-256
/// of its item numbers in order, so stores with the same assortment share one snapshot cut.
/// </summary>
public static container refresh(InventLocationId _warehouse, boolean _on)
{
    HSMobileOpsSyncAssortItem row;
    HSMobileOpsSyncAssortItem newRow;
    Set                       assorted;
    Set                       kept = new Set(Types::String);
    SetEnumerator             itemEnum;
    RecordInsertList          rows;

    System.Text.StringBuilder signature = new System.Text.StringBuilder();
    System.Security.Cryptography.SHA256 sha;

    if (!_warehouse)
    {
        return [0, ''];
    }
    if (!_on)
    {
        ttsbegin;
        delete_from row where row.Warehouse == _warehouse;
        ttscommit;
        return [0, ''];
    }
    assorted = HSMobileOpsCountAssortment::assortedItems(_warehouse);
    rows = new RecordInsertList(tableNum(HSMobileOpsSyncAssortItem));
    ttsbegin;
    while select forUpdate row
        where row.Warehouse == _warehouse
    {
        if (assorted.in(row.ItemId))
        {
            kept.add(row.ItemId);
        }
        else
        {
            row.delete();
        }
    }
    itemEnum = assorted.getEnumerator();
    while (itemEnum.moveNext())
    {
        // A Set enumerates in order: the same items give the same signature.
        signature.Append(itemEnum.current());
        signature.Append("\n");
        if (!kept.in(itemEnum.current()))
        {
            newRow.clear();
            newRow.Warehouse = _warehouse;
            newRow.ItemId    = itemEnum.current();
            rows.add(newRow);
        }
    }
    rows.insertDatabase();
    ttscommit;
    sha = System.Security.Cryptography.SHA256::Create();
    return [assorted.elements(), strLwr(strReplace(System.BitConverter::ToString(
        sha.ComputeHash(System.Text.Encoding::get_UTF8().GetBytes(signature.ToString()))), '-', ''))];
}

/// <summary>The warehouse's item list as a Set - what a store snapshot keeps.</summary>
public static Set itemSet(InventLocationId _warehouse)
{
    HSMobileOpsSyncAssortItem row;
    Set                       items = new Set(Types::String);

    while select ItemId from row
        where row.Warehouse == _warehouse
    {
        items.add(row.ItemId);
    }
    return items;
}

public static boolean exist(InventLocationId _warehouse, ItemId _itemId)
{
    HSMobileOpsSyncAssortItem row;

    select firstOnly RecId from row
        where row.Warehouse == _warehouse
           && row.ItemId    == _itemId;
    return row.RecId != 0;
}
